"""
Branding for TestMyIdea: the logo (built in, so there are no image files to lose),
color schemes, and a color display. Everything is cosmetic: if anything here fails,
the app keeps Streamlit's default look.
"""
from __future__ import annotations

import base64

import streamlit as st

THEMES = {
    "Classic": {"bg": "#FFFFFF", "surface": "#F5F7FB", "text": "#1F2937", "muted": "#6B7280",
                "primary": "#4F46E5", "accent": "#0EA5A4", "dark": False},
    "Midnight": {"bg": "#0B1020", "surface": "#151B2E", "text": "#E5E7EB", "muted": "#94A3B8",
                 "primary": "#818CF8", "accent": "#2DD4BF", "dark": True},
    "Ocean": {"bg": "#F0F7FF", "surface": "#DCEBFA", "text": "#0F2A44", "muted": "#4B6B88",
              "primary": "#0369A1", "accent": "#06B6D4", "dark": False},
    "Forest": {"bg": "#F3F8F2", "surface": "#E1EEDD", "text": "#1C2B1A", "muted": "#5B6E57",
               "primary": "#2F7D32", "accent": "#B7791F", "dark": False},
    "Sunset": {"bg": "#FFF7F0", "surface": "#FDE7D7", "text": "#3B1F12", "muted": "#8A5A44",
               "primary": "#E4572E", "accent": "#7C3AED", "dark": False},
    "Terminal": {"bg": "#0A0F0A", "surface": "#121A12", "text": "#D1FAE5", "muted": "#6EE7B7",
                 "primary": "#22C55E", "accent": "#FACC15", "dark": True},
}
ROLE_LABELS = {"bg": "Background", "surface": "Panels", "text": "Text", "muted": "Secondary text",
               "primary": "Primary", "accent": "Accent"}
WORDMARK_LIGHT_B64 = ""
WORDMARK_DARK_B64 = ""
ICON_B64 = ""


def _img(b64: str) -> bytes:
    return base64.b64decode(b64)


def icon_bytes() -> bytes:
    return _img(ICON_B64)


def current_theme() -> tuple[str, dict]:
    name = st.session_state.get("theme_name", "Classic")
    return name, THEMES.get(name, THEMES["Classic"])


def _css(t: dict) -> str:
    return f"""
<style>
.stApp {{ background: {t['bg']}; color: {t['text']}; }}
[data-testid="stHeader"] {{ background: {t['bg']}; }}
[data-testid="stSidebar"] {{ background: {t['surface']}; }}
.stApp h1, .stApp h2, .stApp h3, .stApp h4, .stApp h5, .stApp p, .stApp li, .stApp label,
[data-testid="stMetricValue"], [data-testid="stMarkdownContainer"] {{ color: {t['text']}; }}
[data-testid="stCaptionContainer"], [data-testid="stMetricLabel"] p {{ color: {t['muted']} !important; }}
button[data-baseweb="tab"][aria-selected="true"] p {{ color: {t['primary']} !important; }}
[data-baseweb="tab-highlight"] {{ background-color: {t['primary']} !important; }}
.stButton > button, .stFormSubmitButton > button {{ border-color: {t['primary']}; color: {t['primary']};
    background: {t['surface']}; }}
.stButton > button[kind="primary"], .stFormSubmitButton > button[kind="primary"],
[data-testid="stBaseButton-primary"], [data-testid="stBaseButton-primaryFormSubmit"] {{
    background: {t['primary']} !important; border-color: {t['primary']} !important; color: #FFFFFF !important; }}
.stTextInput input, .stNumberInput input, .stTextArea textarea, [data-baseweb="select"] > div,
[data-testid="stChatInput"] textarea {{ background: {t['surface']} !important; color: {t['text']} !important; }}
[data-testid="stChatMessage"] {{ background: {t['surface']}; border-radius: 12px; }}
[data-testid="stExpander"] details {{ background: {t['surface']}; border-color: {t['surface']}; }}
[data-testid="stProgress"] div[role="progressbar"] > div > div {{ background-color: {t['primary']}; }}
a {{ color: {t['accent']}; }}
</style>"""


def swatches_html(t: dict, compact: bool = False) -> str:
    size = 26 if compact else 44
    cells = []
    for role, label in ROLE_LABELS.items():
        hexv = t[role]
        cap = "" if compact else (f"<div style='font-size:11px;margin-top:4px;color:{t['muted']}'>{label}"
                                  f"<br><code style='font-size:10px'>{hexv}</code></div>")
        cells.append(f"<div style='text-align:center;flex:1;min-width:{size}px'>"
                     f"<div title='{label} {hexv}' style='height:{size}px;border-radius:8px;background:{hexv};"
                     f"border:1px solid rgba(127,127,127,.35)'></div>{cap}</div>")
    return f"<div style='display:flex;gap:6px;margin:4px 0 8px'>{''.join(cells)}</div>"


def apply_branding():
    """Logo in the top-left, theme picker + color display in the sidebar, theme CSS."""
    try:
        if "_pending_theme" in st.session_state:
            st.session_state["theme_name"] = st.session_state.pop("_pending_theme")
        with st.sidebar:
            st.markdown("### 🎨 Appearance")
            st.selectbox("Color scheme", list(THEMES), key="theme_name")
            name, t = current_theme()
            st.markdown(swatches_html(t), unsafe_allow_html=True)
        st.markdown(_css(t), unsafe_allow_html=True)
        st.logo(_img(WORDMARK_DARK_B64 if t["dark"] else WORDMARK_LIGHT_B64),
                size="large", icon_image=icon_bytes())
    except Exception:
        pass  # cosmetic only: never block the app


def header():
    """Wordmark at the top-left of the page, matched to light/dark schemes."""
    _, t = current_theme()
    st.image(_img(WORDMARK_DARK_B64 if t["dark"] else WORDMARK_LIGHT_B64), width=380)


def color_display():
    """Every color scheme side by side, with a button to switch."""
    st.caption("Pick a scheme here or in the sidebar. Each one restyles the whole app.")
    for name, t in THEMES.items():
        c1, c2 = st.columns([1, 4])
        c1.markdown(f"**{name}**" + (" 🌙" if t["dark"] else ""))
        if c1.button("Use", key=f"use_theme_{name}"):
            st.session_state["_pending_theme"] = name   # applied before the picker is drawn
            st.rerun()
        c2.markdown(swatches_html(t, compact=True), unsafe_allow_html=True)